-- Source rows for production.FactFacilityYearProduction: the logic of the table.
-- Generated by `python -m fde render` from models/gold/production/FactFacilityYearProduction.sql. Do not edit: change the spec and render again.

IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[FactFacilityYearProductionSource]
AS
with

facility_year as (

    select * from [lh_silver].[production].[facilityyearproduction]

),

facility as (

    select * from [facilities].[DimFacility]

)

select
    facility_year.FacilityYear_BK,
    coalesce(facility.DimFacility_SK, -1) as DimFacility_SK,
    facility_year.ReportingYear,
    facility_year.OreMinedTonnes,
    facility_year.OreProcessedTonnes,
    facility_year.ConcentrateTonnes,
    facility_year.WasteTonnes
from facility_year
left join facility
    on facility.Facility_BK = facility_year.Facility_BK
GO
